challenges.solution:
function parseDate(text) {
  const m = text.match(/(?<year>\d{4})-(?<month>\d{2})-(?<day>\d{2})/)
  if (!m) return null
  const { year, month, day } = m.groups
  return { year: Number(year), month: Number(month), day: Number(day) }
}

function readSettings(text) {
  const settings = {}
  for (const m of text.matchAll(/(\w+)=(\w+)/g)) {
    settings[m[1]] = m[2]
  }
  return settings
}

function doubleNumbers(text) {
  return text.replace(/\d+/g, (n) => String(Number(n) * 2))
}

function titleCase(text) {
  return text.toLowerCase().replace(/\b\w/g, (c) => c.toUpperCase())
}

function mentions(post) {
  const names = [...post.matchAll(/@(\w+)/g)].map((m) => m[1])
  return [...new Set(names)]
}

function mask(text) {
  return text.replace(/\d{4}([ -])\d{4}\1\d{4}\1(\d{4})/g, (whole, sep, last) => ["****", "****", "****", last].join(sep))
}

function fill(template, values) {
  return template.replace(/\{\{\s*(\w+)\s*\}\}/g, (whole, key) => (key in values ? String(values[key]) : whole))
}

function isYes(answer) {
  return ["yes", "y", "yeah", "yep"].includes(answer.trim().toLowerCase())
}

function wordCount(text) {
  return (text.match(/[\w']+/g) ?? []).length
}

function sameWord(a, b) {
  const key = (w) => w.trim().normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase()
  return key(a) === key(b)
}

function tally(votes) {
  const counts = {}
  for (const v of votes.map((v) => v.trim().toLowerCase()).filter((v) => v !== "")) {
    counts[v] = (counts[v] ?? 0) + 1
  }
  return counts
}

function initials(name) {
  const plain = name.normalize("NFD").replace(/[\u0300-\u036f]/g, "")
  return (plain.match(/[a-z]+/gi) ?? []).map((part) => part[0].toUpperCase()).join("")
}

function cleanPhone(raw) {
  const d = raw.replace(/\D/g, "")
  if (d.length !== 10) return null
  return `(${d.slice(0, 3)}) ${d.slice(3, 6)}-${d.slice(6)}`
}

