challenges.solution:
function toCsv(rows) {
  if (rows.length === 0) return ""
  const columns = Object.keys(rows[0])
  const lines = rows.map((row) => columns.map((c) => row[c]).join(","))
  return [columns.join(","), ...lines].join("\n")
}

const csv = `date,item,qty,price
2026-03-01,tea,2,2.50
2026-03-01,cake,1,3.20
2026-03-02,tea,3,2.50
2026-03-02,juice,2,1.95`
function perItem(csv) {
  const totals = {}
  for (const line of csv.trim().split("\n").slice(1)) {
    const [, item, qty] = line.split(",")
    totals[item] = (totals[item] ?? 0) + Number(qty)
  }
  return totals
}

function selectColumns(csv, wanted) {
  const lines = csv.trim().split("\n").map((line) => line.split(","))
  const indexes = wanted.map((col) => lines[0].indexOf(col))
  return lines.map((values) => indexes.map((i) => values[i]).join(",")).join("\n")
}

function splitCsvLine(line) {
  const values = []
  let current = ""
  let inQuotes = false
  for (let i = 0; i < line.length; i++) {
    const ch = line[i]
    if (ch === '"') {
      if (inQuotes && line[i + 1] === '"') {
        current += '"'
        i++
      } else {
        inQuotes = !inQuotes
      }
    } else if (ch === "," && !inQuotes) {
      values.push(current)
      current = ""
    } else {
      current += ch
    }
  }
  values.push(current)
  return values
}

function csvValue(value) {
  const text = String(value)
  if (/[",\n]/.test(text)) return `"${text.replaceAll('"', '""')}"`
  return text
}

