challenges.solution:
function addDays(date, n) {
  const copy = new Date(date)
  copy.setDate(copy.getDate() + n)
  return copy
}

function formatDate(date) {
  const m = String(date.getMonth() + 1).padStart(2, "0")
  const d = String(date.getDate()).padStart(2, "0")
  return `${date.getFullYear()}-${m}-${d}`
}

function isWeekend(date) {
  const day = date.getDay()
  return day === 0 || day === 6
}

function age(born, on) {
  let years = on.getFullYear() - born.getFullYear()
  const before = on.getMonth() < born.getMonth() || (on.getMonth() === born.getMonth() && on.getDate() < born.getDate())
  if (before) years--
  return years
}

function daysInMonth(year, monthIndex) {
  return new Date(year, monthIndex + 1, 0).getDate()
}

function workingDays(from, to) {
  let count = 0
  const day = new Date(from)
  while (day <= to) {
    const d = day.getDay()
    if (d !== 0 && d !== 6) count++
    day.setDate(day.getDate() + 1)
  }
  return count
}

function ago(then, now) {
  const s = Math.floor((now - then) / 1000)
  if (s < 60) return "just now"
  if (s < 3600) return `${Math.floor(s / 60)} min ago`
  if (s < 86400) return `${Math.floor(s / 3600)} h ago`
  if (s < 7 * 86400) {
    const days = Math.floor(s / 86400)
    return days === 1 ? "1 day ago" : `${days} days ago`
  }
  const pad = (n) => String(n).padStart(2, "0")
  return `${then.getFullYear()}-${pad(then.getMonth() + 1)}-${pad(then.getDate())}`
}

