function importKind(line) {
  const t = line.trim()
  if (/^import\s*\{/.test(t)) return "named"
  if (/^import\s*\*\s*as\s+\w+/.test(t)) return "namespace"
  if (/^import\s+\w+\s+from/.test(t)) return "default"
  return "none"
}

const factories = new Map()
const loaded = new Map()
function define(name, factory) {
  factories.set(name, factory)
}
function load(name) {
  if (loaded.has(name)) return loaded.get(name)
  if (!factories.has(name)) throw new Error(`No module ${name}`)
  const exports = factories.get(name)()
  loaded.set(name, exports)
  return exports
}

function loadOrder(graph, start) {
  const order = []
  const done = new Set()
  function visit(name) {
    if (done.has(name)) return
    done.add(name)
    for (const dep of graph[name] ?? []) visit(dep)
    order.push(name)
  }
  visit(start)
  return order
}

function findCycle(graph) {
  const visiting = new Set()
  const done = new Set()
  function visit(name) {
    if (visiting.has(name)) return true
    if (done.has(name)) return false
    visiting.add(name)
    for (const dep of graph[name] ?? []) {
      if (visit(dep)) return true
    }
    visiting.delete(name)
    done.add(name)
    return false
  }
  return Object.keys(graph).some((name) => visit(name))
}

