challenges.solution:
const FREE_FROM = 50
const FLAT_RATE = 4.99
function shipping(subtotal) {
  return subtotal >= FREE_FROM ? 0 : FLAT_RATE
}

function greeting(now) {
  const h = now.getHours()
  if (h < 12) return "Good morning"
  if (h < 18) return "Good afternoon"
  return "Good evening"
}

const RATES = { PT: 4, ES: 5, FR: 7, DE: 8 }
const OTHER = 12
function shippingTo(country) {
  return RATES[country] ?? OTHER
}

function makeStore(storage) {
  return {
    save(key, value) {
      storage.set(key, JSON.stringify(value))
    },
    load(key, fallback) {
      const text = storage.get(key)
      return text === undefined ? fallback : JSON.parse(text)
    },
  }
}

function parse(line) {
  const [name, age] = line.split(",")
  return { name: name.trim(), age: Number(age) }
}
function isValid(person) {
  return person.name !== "" && person.age >= 0 && person.age <= 130
}
function describe(line) {
  const person = parse(line)
  return isValid(person) ? `${person.name} is ${person.age}` : `Invalid: ${line}`
}

function makeEmitter() {
  const listeners = new Map()
  return {
    on(event, fn) {
      listeners.set(event, [...(listeners.get(event) ?? []), fn])
    },
    off(event, fn) {
      listeners.set(event, (listeners.get(event) ?? []).filter((f) => f !== fn))
    },
    emit(event, data) {
      for (const fn of listeners.get(event) ?? []) fn(data)
    },
  }
}

const LEVELS = ["debug", "info", "warn", "error"]
function makeLogger(level, write) {
  const min = LEVELS.indexOf(level)
  return Object.fromEntries(
    LEVELS.map((name, i) => [
      name,
      (msg) => {
        if (i >= min) write(`${name.toUpperCase()}: ${msg}`)
      },
    ]),
  )
}

