challenges.solution:
function paceText(run) {
  const p = run.minutes / run.km
  let m = Math.floor(p)
  let s = Math.round((p - m) * 60)
  if (s === 60) {
    m++
    s = 0
  }
  return `${m}:${String(s).padStart(2, "0")} /km`
}

