function monthly(runs) {
  const groups = {}
  for (const r of runs) {
    const key = r.date.slice(0, 7)
    groups[key] = [...(groups[key] ?? []), r]
  }
  const fmt = new Intl.DateTimeFormat("en-US", { month: "short", year: "numeric", timeZone: "UTC" })
  return Object.keys(groups)
    .sort()
    .map((key) => {
      const list = groups[key]
      const km = list.reduce((s, r) => s + r.km, 0)
      return `${fmt.format(new Date(key + "-01"))}: ${list.length} runs, ${km.toFixed(1)} km`
    })
}

