  ana LIMA ,Ana.Lima@Example.com,555 014 2367,2024-03-09
Ben Okafor,ben@example.com,(555) 014-9911,2025-11-30
kim park,KIM@example.com,555.014.2001,2023-07-15
Ana Lima,ana.lima@example.com,,2024-03-09
Zed,zed-at-example.com,12,2026-01-01`
function rows(csv) {
  const [header, ...lines] = csv.trim().split("\n")
  const columns = header.split(",")
  return lines.map((line) => Object.fromEntries(line.split(",").map((v, i) => [columns[i], v])))
}
const cleanName = (s) => s.trim().replace(/\s+/g, " ").toLowerCase().replace(/\b\w/g, (c) => c.toUpperCase())
const cleanEmail = (s) => s.trim().toLowerCase()
function cleanPhone(s) {
  const d = s.replace(/\D/g, "")
  return d.length === 10 ? `(${d.slice(0, 3)}) ${d.slice(3, 6)}-${d.slice(6)}` : null
}
const validEmail = (s) => /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(s)
const contacts = rows(csv).map((r) => ({ name: cleanName(r.name), email: cleanEmail(r.email), phone: cleanPhone(r.phone), joined: r.joined }))
function merge(contacts) {
  const byEmail = new Map()
  for (const c of contacts) {
    const kept = byEmail.get(c.email)
    if (!kept) {
      byEmail.set(c.email, { ...c })
      continue
    }
    for (const k of Object.keys(c)) {
      if (kept[k] == null || kept[k] === "") kept[k] = c[k]
    }
  }
  return [...byEmail.values()]
}

