challenges.solution:
function totals(lines, taxRate) {
  const round = (n) => Math.round(n * 100) / 100
  const subtotal = round(lines.reduce((s, l) => s + l.qty * l.unit, 0))
  const tax = round(subtotal * taxRate)
  return { subtotal, tax, total: round(subtotal + tax) }
}

function dueDate(issued, days) {
  const d = new Date(issued + "T00:00:00Z")
  d.setUTCDate(d.getUTCDate() + days)
  return d.toISOString().slice(0, 10)
}

function checkOrder(order) {
  if (!Array.isArray(order.lines) || order.lines.length === 0) throw new Error("No lines")
  for (const line of order.lines) {
    const ok = (x) => typeof x === "number" && x > 0
    if (!ok(line.qty) || !ok(line.unit)) throw new Error(`Bad line: ${line.item}`)
  }
  if (!/^\d{4}-\d{2}-\d{2}$/.test(order.issued ?? "")) throw new Error("Bad date")
  return true
}

const usd = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" })
function lineText(line) {
  const total = Math.round(line.qty * line.unit * 100) / 100
  return line.item.padEnd(16) + String(line.qty).padStart(5) + " × " + usd.format(line.unit).padEnd(8) + usd.format(total).padStart(15)
}

